const body = $json.body || $json;
const sub = body.subscription || body;
const alerts = Array.isArray(body.welcome_alerts) ? body.welcome_alerts : [];
const recent = Array.isArray(body.recent_matches) ? body.recent_matches : [];
if (!sub.email) throw new Error('email missing');

function esc(s) { return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;'); }
function fmtDate(d) { try { return d ? new Date(d).toLocaleDateString('en-IN', { day:'numeric', month:'long', year:'numeric' }) : 'Unknown'; } catch(e) { return String(d); } }

let billCards = '';
for (const a of alerts.slice(0, 3)) {
  const summaryHtml = esc(a.summary).replace(/\n/g, '<br>');
  billCards += '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-left:4px solid #7c3aed;border-radius:12px;padding:20px;margin-bottom:16px;">'
    + '<h2 style="margin:0 0 6px;color:#0f172a;font-size:17px;">' + esc(a.bill_title) + '</h2>'
    + '<p style="margin:0 0 12px;color:#64748b;font-size:13px;">Ministry of ' + esc(a.bill_ministry) + ' &bull; Status: ' + esc(a.bill_status) + '</p>'
    + '<div style="color:#334155;font-size:14px;line-height:1.65;">' + summaryHtml + '</div>'
    + (a.bill_url ? '<p style="margin:14px 0 0;"><a href="' + a.bill_url + '" style="color:#7c3aed;font-weight:600;">Read the full bill on PRS India</a></p>' : '')
    + '</div>';
}

let recentSection = '';
if (!billCards && recent.length > 0) {
  let rows = '';
  for (const m of recent.slice(0, 3)) {
    const titleHtml = m.url ? '<a href="' + m.url + '" style="color:#0f172a;font-weight:600;text-decoration:none;">' + esc(m.title) + '</a>' : '<strong style="color:#0f172a;">' + esc(m.title) + '</strong>';
    rows += '<tr><td style="padding:10px 8px;border-bottom:1px solid #e2e8f0;">' + titleHtml
      + '<div style="color:#64748b;font-size:12px;margin-top:2px;">' + esc(m.ministry) + ' &bull; ' + esc(m.status) + ' &bull; ' + fmtDate(m.introduction_date) + '</div></td></tr>';
  }
  recentSection = '<p style="color:#334155;font-size:14px;">You will now get an email whenever a new bill matches your topics. Here are three recent examples:</p>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">' + rows + '</table>';
}

const topics = [].concat(sub.keywords || [], sub.ministries || []).join(', ') || 'your topics';
const subject = billCards ? 'Your VidhanAI bill tracker is live' : 'Welcome to VidhanAI alerts';

const html = '<!doctype html><html><body style="margin:0;padding:0;background:#eef2f7;font-family:Arial,sans-serif;">'
  + '<div style="max-width:640px;margin:0 auto;padding:24px;">'
  + '<div style="text-align:center;margin-bottom:20px;"><span style="display:inline-block;background:#7c3aed;color:#fff;border-radius:12px;padding:10px 16px;font-size:18px;font-weight:700;">VidhanAI</span></div>'
  + '<div style="background:#ffffff;border-radius:16px;padding:28px;border:1px solid #e2e8f0;">'
  + '<h1 style="margin:0 0 8px;color:#0f172a;font-size:22px;">Welcome to VidhanAI Alerts</h1>'
  + '<p style="margin:0 0 18px;color:#475569;font-size:14px;line-height:1.6;">You are now tracking <strong>' + esc(topics) + '</strong>. This inbox is your window into the Indian Parliament.</p>'
  + billCards + recentSection
  + (billCards || recent.length ? '' : '<p style="color:#334155;font-size:14px;">No matching bills yet - you will be the first to know when one lands.</p>')
  + '<hr style="border:none;border-top:1px solid #e2e8f0;margin:22px 0;">'
  + '<p style="margin:0;color:#94a3b8;font-size:12px;line-height:1.6;">Summaries are AI-generated for educational purposes and may contain errors - always check the official bill text on PRS India.</p>'
  + '</div></div></body></html>';

return { json: { email: sub.email, subject, html } };
